insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 1, 'Which set of assumptions did the Associate (beginner) typewell workflow rely on?', '["Density-only porosity, clean-sand Archie saturation, Larionov tertiary Vsh, and given parameters","Neutron-density porosity, Simandoux saturation, linear Vsh, and fitted parameters","Sonic-only porosity, Indonesia saturation, Clavier Vsh, and core-calibrated parameters","Multi-method porosity, Archie saturation, linear Vsh, and a Pickett-validated Rw"]'::jsonb, 0, 'The beginner workflow used the density log alone for porosity, clean-sand Archie, the Larionov tertiary transform, and accepted every parameter as given.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 2, 'Why does the Archie equation overstate water saturation in a shaly sand?', '["Clay minerals lower the gamma ray reading, which biases the porosity input","Archie attributes all measured conductivity to pore water, so clay conduction is booked as extra water","Shale increases the resistivity of the formation, which Archie reads as hydrocarbon","The n exponent doubles in the presence of clay-bound water"]'::jsonb, 1, 'Archie assumes brine is the only conductor. Conductive clay adds signal that the equation can only explain as more water.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 3, 'The Professional capstone grades six numbers. Which zone or interval do they come from?', '["SAND_B means plus a fit in the SAND_A fringe","Whole-well means over 1990 to 2090 m","SAND_A (2010 to 2030 m) means plus the Pickett fit in the water leg","The shale interval around 2000 m"]'::jsonb, 2, 'Four of the six are SAND_A zone means; the two Pickett values are fitted in the 2075 to 2078 m water leg.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 4, 'On the typewell, the sonic anchors are dt_ma = 182 and dt_fl = 656 microseconds per metre. What are their classic imperial equivalents?', '["40 and 140 us/ft","55.5 and 200 us/ft","89 and 189 us/ft","182 and 656 us/ft"]'::jsonb, 1, '182 us/m converts to 55.5 us/ft and 656 us/m to 200 us/ft, the classic sandstone matrix and fluid pair.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 5, 'What physical quantity governs the neutron log response?', '["The electron density of the formation","The acoustic impedance contrast at the borehole wall","The hydrogen index of the formation","The cation exchange capacity of the clay fraction"]'::jsonb, 2, 'Fast neutrons are slowed most effectively by hydrogen, so the count rate reflects hydrogen per unit volume, reported in porosity units.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 6, 'Where does the shale resistivity value Rsh = 2.0 ohm.m used by the workflow come from?', '["A laboratory measurement on a shale core plug","The deep resistivity reading where RT flattens in the thick shale","The Pickett plot intercept at 100 percent porosity","A regional default supplied with the app"]'::jsonb, 1, 'Rsh is read from the well itself: in the thick shale the deep resistivity flattens at 2 ohm.m.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 7, 'Why does the Professional workflow switch from Larionov tertiary to the linear Vsh transform?', '["The linear transform is more accurate for young clastic rocks","Larionov tertiary cannot be clamped to the 0 to 1 range","The gamma ray anchors change at the intermediate tier","Shaly-sand saturation equations were calibrated with conservative clay volumes, and an upper-bound Vsh keeps the correction honest"]'::jsonb, 3, 'Simandoux and Indonesia were calibrated in the era of the linear index; feeding them a smaller Larionov volume under-corrects for clay conductivity.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 8, 'Using the typewell anchors (clean 20, clay 120 API), what is the clamped linear Vsh for a gamma ray reading of 15 API?', '["0","-0.05","0.05","0.15"]'::jsonb, 0, 'The raw index is (15 - 20)/100 = -0.05, and the clamp raises anything below zero to exactly 0.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 9, 'At IGR = 0.5, the linear transform gives Vsh = 0.50. What does Larionov tertiary give at the same index?', '["0.0746","0.2162","0.3300","0.4852"]'::jsonb, 1, 'Larionov tertiary at IGR 0.5 is 0.083 x (2^1.85 - 1) = 0.2162, less than half the linear value.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 10, 'In the shaly-sand workflow, what job does the Vsh curve perform?', '["It corrects the neutron log for borehole washout","It scales the porosity cutoff zone by zone","It is a correction term that removes clay conductivity from the resistivity signal before saturation is computed","It only excludes samples through the shale cutoff, as in the beginner workflow"]'::jsonb, 2, 'At this tier Vsh feeds the Simandoux and Indonesia equations, which subtract the clay contribution to conductivity; the cutoff role still exists but is not the reason for the linear switch.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 11, 'The neutron-density porosity used by this workflow is computed how?', '["The root mean square of phiD and NPHI","The simple average (phiD + NPHI) / 2","The minimum of phiD and NPHI","phiD corrected by subtracting Vsh times NPHI"]'::jsonb, 1, 'The workflow uses the arithmetic average of density porosity and the neutron reading.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 12, 'At 2020 m the typewell reads RHOB 2.3035 and NPHI 0.13. With rho_ma 2.65 and rho_fl 1.0, what is phiND?', '["0.2100","0.1300","0.1700","0.1762"]'::jsonb, 2, 'phiD = (2.65 - 2.3035)/1.65 = 0.2100, so phiND = (0.2100 + 0.13)/2 = 0.1700. The value 0.1762 is the SAND_A zone mean, not this sample.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 13, 'What does the Pickett plot fit in the water leg deliver to the workflow?', '["The cementation exponent m from the slope and the product a times Rw from the line position","The shale resistivity Rsh and the saturation exponent n","The matrix density and fluid density for the density porosity","The porosity and saturation cutoffs for net pay"]'::jsonb, 0, 'On log-log axes the water line''s slope measures m and its position measures the product a.Rw; on this well the fit returns 2.000 and 0.0500 ohm.m.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 14, 'At 2020 m the linear Vsh is 0. What do the Simandoux and Indonesia models return there, given that Archie returns 0.4324?', '["Slightly lower values, because the clay correction always reduces Sw","Exactly 0.4324 from both, because both models degenerate to Archie at zero Vsh","Slightly higher values, because the models add the shale conductivity term","Undefined values, because shaly-sand models require Vsh above zero"]'::jsonb, 1, 'Both models collapse exactly to Archie in clean rock, so all three agree at 0.4324 where Vsh = 0.'),
  ('petrophysics', 'intermediate', 'module', 'm01-the-professional-workflow', 15, 'Which pair of capstone numbers is fitted rather than averaged over SAND_A?', '["The Simandoux and Indonesia saturation values","The neutron-density and Wyllie sonic porosity values","The net thickness and net-to-gross values","The Pickett a.Rw and cementation exponent m"]'::jsonb, 3, 'Four graded numbers are SAND_A means; a.Rw and m come from the straight-line fit in the 2075 to 2078 m water leg.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 1, 'What quantity does the sonic curve DT record?', '["The velocity of the compressional wave in kilometres per second","The total travel time from transmitter to the farthest receiver","The compressional interval transit time, the time to cross one unit length of formation","The amplitude of the first compressional arrival"]'::jsonb, 2, 'DT is the interval transit time, time per unit length, obtained from arrival-time differences across the receiver spacing. It is the reciprocal of velocity, not the velocity itself.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 2, 'The classic sandstone matrix transit time is 55.5 us/ft. What is this value in the metric units the typewell uses, and how is it obtained?', '["182 us/m, by dividing 55.5 by 0.3048","182 us/m, by multiplying 55.5 by 0.3048","169 us/m, by multiplying 55.5 by 3.048","656 us/m, by dividing 200 by 0.3048"]'::jsonb, 0, 'One foot is 0.3048 m, so time per foot converts to time per metre by dividing by 0.3048: 55.5 / 0.3048 = 182 us/m. The 656 value is the fluid anchor, converted from 200 us/ft the same way.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 3, 'Why does interval transit time increase with porosity?', '["Porous rock is denser, and denser rock transmits sound more slowly","Pore fluid transmits the wave much more slowly than the mineral frame, so more fluid-filled volume raises the composite transit time","The tool''s receivers are farther apart in porous formations","Porosity increases the borehole diameter, lengthening the mud path"]'::jsonb, 1, 'The frame is fast (about 182 us/m for quartz) and pore water slow (about 656 us/m). Replacing frame with fluid along the path adds transit time in proportion to porosity.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 4, 'On a sonic log you see abrupt spikes to very high DT that reset just as abruptly, in an interval of gas-cut mud. The most likely cause is:', '["A washout enlarging the borehole","Genuine high porosity streaks","The wrong matrix value in the transform","Cycle skipping, where the timing circuit misses the weak first arrival and triggers on a later cycle"]'::jsonb, 3, 'Weak first arrivals in gas-cut mud cause the detector to skip to a later waveform cycle, producing spiky, spurious high DT. The signature of abrupt jumps and resets distinguishes it from real porosity.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 5, 'Using the typewell anchors (matrix 182, fluid 656 us/m), the Wyllie porosity for a sample reading DT of 300 us/m is closest to:', '["0.1800","0.2489","0.3536","0.4572"]'::jsonb, 1, 'phi = (300 - 182)/(656 - 182) = 118/474 = 0.2489.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 6, 'A rock sample reads DT exactly equal to the matrix value of 182 us/m. The Wyllie transform computes:', '["Zero porosity, because there is no excess transit time over pure matrix","Porosity of 1, because the reading sits on an anchor","An undefined result, because the denominator vanishes","Negative porosity, indicating bad hole"]'::jsonb, 0, 'The numerator (DT minus matrix time) is zero, so porosity is zero. The transform is a linear interpolation between the matrix anchor (porosity 0) and the fluid anchor (porosity 1).'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 7, 'The Wyllie time average is derived from which physical idealisation?', '["The wave scatters off pore surfaces in proportion to porosity","The wave travels fastest along the borehole wall","The wave crosses fluid and matrix segments in series, so total time is the volume-weighted sum of the two transit times","The wave''s amplitude decays exponentially with porosity"]'::jsonb, 2, 'The series-path assumption gives DT = phi times the fluid time plus (1 - phi) times the matrix time, which rearranges directly into the time-average porosity equation.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 8, 'In a shallow, poorly compacted sand, the classical way to keep using the Wyllie transform is to:', '["Raise the fluid anchor above 656 us/m","Lower the matrix anchor below 182 us/m","Multiply the computed porosity by a factor greater than 1","Divide the computed porosity by a compaction factor Cp greater than 1, estimated from adjacent shale readings"]'::jsonb, 3, 'Undercompaction makes the frame slow and Wyllie read high, so the classical correction divides by Cp > 1. The typewell is compacted and runs with Cp = 1.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 9, 'At 2020 m the typewell reads DT of 281.54 us/m. With C = 0.67 and matrix 182 us/m, the Raymer-Hunt-Gardner porosity is closest to:', '["0.2100","0.2369","0.3536","0.1400"]'::jsonb, 1, 'phi = 0.67 x (281.54 - 182)/281.54 = 0.67 x 0.3536 = 0.2369. The 0.2100 option is the Wyllie value at the same depth and 0.3536 is the unscaled ratio.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 10, 'Structurally, the RHG approximation differs from the Wyllie time average because RHG:', '["Divides the excess transit time by the measured DT itself and scales by an empirical constant, with no fluid value in the formula","Divides by the fixed matrix-to-fluid span of 474 us/m","Requires a separate compaction factor Cp in slow formations","Uses the shear rather than the compressional transit time"]'::jsonb, 0, 'RHG computes C x (DT - DTma)/DT with C = 0.67; the fluid anchor disappears and the empirical constant absorbs it, making the response curved rather than linear.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 11, 'In which situation is RHG generally preferred over the plain Wyllie time average?', '["Compacted sands where density and Wyllie already agree","Any interval where a bigger porosity is desired","Uncompacted or slow formations, because RHG fits field data across the porosity range without a separate compaction correction","Shales, where it returns effective rather than apparent porosity"]'::jsonb, 2, 'RHG was calibrated to correct Wyllie''s underestimation in uncompacted rock without needing Cp. In compacted sections it overshoots, and no transform returns effective porosity in shale.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 12, 'Over SAND_A the typewell zone means are: density 0.2022, Wyllie 0.2069, RHG 0.2344. The professional reading of this table is:', '["RHG is correct because it is the most recent method","The three should be averaged to 0.2145 and booked","The density tool has failed and the sonic values should be booked","Density and Wyllie agree within half a porosity unit, confirming a clean compacted liquid-filled sand, while RHG reads high as expected for a compacted section"]'::jsonb, 3, 'Agreement of two independent physics is the quality control; RHG running about 2.7 porosity units hot is the predicted behaviour of its built-in compaction compensation in rock that needs none.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 13, 'At 2000 m the shale computes a Wyllie porosity of 0.1200 while the density porosity is 0.0606. The sonic value is best described as:', '["Apparent porosity inflated by slow clay minerals and bound water, not connected pore space","The correct effective porosity, since the sonic is unaffected by shale","Proof that the density matrix value is wrong in this interval","Evidence of gas in the shale"]'::jsonb, 0, 'Clay slows the compressional wave, so the transform converts the excess time into porosity that is not producible pore volume. Sonic porosity in shale is diagnostic, not bookable.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 14, 'In the water leg at 2076 m, Wyllie gives 0.0980 and density gives 0.0980. Why does this agreement matter beyond the single depth?', '["It proves the water leg contains no hydrocarbons","It sets the Sw cutoff for the net pay calculation","It establishes confidence in the porosity carried into the Pickett plot fit that will be made in this same interval","It shows the neutron log is not needed on this well"]'::jsonb, 2, 'A clean, compacted, fully water-saturated sand is the calibrated domain of both transforms. Verified porosity in the leg underpins the Pickett fit performed there two modules later.'),
  ('petrophysics', 'intermediate', 'module', 'm02-sonic-porosity', 15, 'How does gas in the pore space affect sonic porosity?', '["It lowers DT, so computed porosity reads too low","It raises DT well beyond the water-filled prediction, so computed porosity reads too high, most severely in unconsolidated sands","It has no effect, because the head wave travels only in the matrix","It causes the density and sonic porosities to agree exactly"]'::jsonb, 1, 'Replacing liquid with gas slows the rock dramatically; DT and therefore computed porosity overshoot. The typewell has no gas leg, but the symptom must be recognised.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 1, 'Why does the neutron tool respond mainly to hydrogen rather than to the rock matrix?', '["Hydrogen is radioactive and emits neutrons of its own","Matrix minerals absorb all neutrons before they reach the detector","A fast neutron loses energy most efficiently in collisions with a nucleus of about its own mass, and hydrogen is the only common nucleus that qualifies","The tool is electrically insulated from everything except pore fluid"]'::jsonb, 2, 'Neutron slowing is dominated by elastic collisions with hydrogen nuclei, which have nearly the same mass as the neutron; heavier nuclei barely slow it.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 2, 'The typewell NPHI curve is delivered on which reference, and in what units?', '["A sandstone matrix scale, in volume-fraction porosity units","A limestone matrix scale, in API units","A dolomite matrix scale, in g/cc","No matrix reference; it is a raw count rate"]'::jsonb, 0, 'The typewell neutron is sandstone-referenced and reported in v/v, so in clean water-filled sandstone it reads porosity directly.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 3, 'Besides free pore water, what is the main contributor that pushes a neutron reading upward?', '["Heavy minerals in the matrix","Water bound in and on clay minerals","Drilling-induced fractures","Cementation between sand grains"]'::jsonb, 1, 'Clay-bound and adsorbed water is hydrogen the tool cannot distinguish from pore water, which is why shales read high neutron porosity.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 4, 'How does gas in the pore space affect the neutron reading, and why?', '["It raises NPHI because gas molecules are small and mobile","It has no effect because the tool only senses the matrix","It raises NPHI because gas scatters neutrons more strongly than water","It lowers NPHI because gas has a much lower hydrogen density per unit volume than liquid"]'::jsonb, 3, 'Hydrogen index per unit volume is far lower for gas than for water or oil, so a gas-filled pore contributes less to the neutron response and NPHI drops.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 5, 'At 2020 m the density porosity is 0.2100 and NPHI is 0.13. What neutron-density porosity does the course''s combination give?', '["0.2100","0.1700","0.1300","0.0800"]'::jsonb, 1, 'The engine books the simple average: (0.2100 + 0.13)/2 = 0.1700.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 6, 'What is the core argument for combining neutron and density porosities instead of using either alone?', '["Their errors run in opposite directions in shale and in gas, so an average partly cancels the biases","The neutron tool is always more accurate, and the density adds resolution","Averaging doubles the vertical resolution of the measurement","The two tools share the same physics, so averaging reduces random noise only"]'::jsonb, 0, 'Density and neutron are fooled in opposite directions by both shale and gas; the average inherits only half of each bias, and opposing biases partly cancel.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 7, 'Which neutron-density combination does this course book, and what is the alternative reserved for?', '["The root-mean-square, with the average reserved for shale","A porosity-weighted mean, with the average reserved for carbonates","The simple average, with the root-mean-square variant preferred by some interpreters in gas zones","The minimum of the two curves, with the maximum reserved for water legs"]'::jsonb, 2, 'The engine and capstone use the plain average; the RMS variant weights the larger value more and compensates better for gas, which the typewell does not have.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 8, 'The shale at 2000 m has a neutron-density average of 0.1803. Why is this not a usable effective porosity?', '["The density tool fails completely in shale, so the average is undefined","It is too low; shales typically have effective porosity above 30 percent","The neutron reads shale on a dolomite scale, so the units are wrong","Most of it is clay-bound water counted by the neutron, so it overstates the pore volume hydrocarbons could ever occupy"]'::jsonb, 3, 'The 0.30 neutron reading in shale is mostly clay-bound hydrogen; averaging with the density halves the exaggeration but leaves a total-porosity-flavoured number, not effective porosity.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 9, 'Using the linear shale correction with Vsh = 1.0 and an apparent shale porosity of 0.10, what is the corrected porosity at the 2000 m shale point where the uncorrected average is 0.1803?', '["0.0803","0.1703","0.1000","0.2803"]'::jsonb, 0, 'phi_e = phi - Vsh x phi_shale_apparent = 0.1803 - 1.0 x 0.10 = 0.0803.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 10, 'On a compatible matrix scale, the density porosity swings above the neutron porosity and the curves cross over. What does this classically indicate?', '["A washed-out borehole","Gas in the pore space","A laminated shale sequence","An error in the depth alignment of the two curves"]'::jsonb, 1, 'Gas lowers bulk density (raising density porosity) and lowers hydrogen index (lowering neutron porosity); the resulting crossover is the classic gas signature.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 11, 'No neutron-density crossover appears anywhere on the typewell. What does the course conclude from this absence?', '["The neutron tool was miscalibrated over the whole section","The section contains no shale","The fluids are oil and water only, so no gas effect complicates the porosity pair","The density log must be discarded in favour of the sonic"]'::jsonb, 2, 'The typewell column is oil and water; recognising the absence of the gas pattern is itself a diagnostic conclusion.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 12, 'Which three lithology lines does the app draw on the neutron-density crossplot?', '["Sandstone, Limestone and Dolomite","Sandstone, Shale and Coal","Limestone, Anhydrite and Salt","Quartz, Feldspar and Clay"]'::jsonb, 0, 'The crossplot overlays exactly three clean-matrix lines: Sandstone, Limestone and Dolomite, each graduated in porosity.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 13, 'On the neutron-density crossplot, a point pulled far toward high NPHI with low density porosity, such as the typewell sample at NPHI 0.30 and density porosity 0.0606, indicates what?', '["Gas-filled clean sandstone","A tight carbonate streak","A washout affecting only the neutron tool","Shale, dragged by clay-bound hydrogen"]'::jsonb, 3, 'High neutron with low density porosity is the shale corner of the crossplot; the 2000 m shale plots exactly there.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 14, 'What is the SAND_A zone mean of the booked neutron-density porosity on the typewell?', '["0.2022","0.1762","0.2344","0.2069"]'::jsonb, 1, 'The engine''s SAND_A mean phiND is 0.1762; 0.2022 is density-only, 0.2069 is the Wyllie sonic mean and 0.2344 is the RHG sonic mean.'),
  ('petrophysics', 'intermediate', 'module', 'm03-neutron-density-porosity', 15, 'Why does the intermediate course book the neutron-density average rather than density-only porosity?', '["The density log is unavailable over most of the typewell","Regulations require two porosity tools for booked reserves","Two independent physics temper single-tool bias, and the combination degrades most gracefully when shale or gas disturbs the inputs","The average always gives the highest porosity, which maximises reported volumes"]'::jsonb, 2, 'The average inherits only half of each tool''s bias, defends against the opposing shale and gas effects, and is the engine''s graded convention; here it is actually lower than density-only, so it is not chosen to inflate volumes.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 1, 'What defines a water leg?', '["An interval where the mud filtrate has fully displaced formation water","An interval known to be fully water saturated, below the free water level","Any interval whose resistivity is below 10 ohm.m","The deepest logged interval of a well"]'::jsonb, 1, 'A water leg sits below the free water level, so the pores carry water and nothing else, making Sw = 1 known in advance.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 2, 'Why is a water leg so valuable for parameter calibration?', '["Because porosity is always highest there","Because the resistivity tool is most accurate at low readings","Because with Sw = 1 known, Archie collapses to a direct relationship between Rt and porosity, leaving the parameters nowhere to hide","Because shale volume is always zero below the free water level"]'::jsonb, 2, 'Setting Sw = 1 removes the one unknowable variable, so Rt = aRw/phi^m relates two measured quantities through the parameters alone.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 3, 'Which combination of signs identifies a water leg on logs?', '["High resistivity, resistivity tracking porosity, gas shows","Low resistivity for the porosity, resistivity tracking porosity, no hydrocarbon shows","Low gamma ray, high resistivity, mud losses","High neutron porosity, low density porosity, oil shows"]'::jsonb, 1, 'Water conducts, so resistivity is low and moves only with porosity; shows data must also confirm the absence of hydrocarbons.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 4, 'On a Pickett plot with porosity on x and deep resistivity on y, both on logarithmic axes, water-saturated points fall on a straight line with slope:', '["+m","-n","+aRw","-m"]'::jsonb, 3, 'Taking logs of Archie at Sw = 1 gives log Rt = log(aRw) - m log phi, a line of slope -m.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 5, 'What does the extrapolated intercept of the Pickett water line at porosity = 1 give you?', '["The product a times Rw","Rw alone","The cementation exponent m","The saturation exponent n"]'::jsonb, 0, 'At log phi = 0 the water-line equation leaves log(aRw); the plot delivers the product as one number, not a and Rw separately.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 6, 'Why does the course report the fitted quantity as aRw rather than as Rw?', '["Because a is always larger than Rw","Because the Pickett fit cannot separate a from Rw; any pair with the same product draws the same line","Because Rw varies with depth while aRw does not","Because the tolerance on Rw is too tight to grade"]'::jsonb, 1, 'The intercept fixes only the product; separating a from Rw needs outside information such as a laboratory water sample.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 7, 'The typewell water leg spans 2075 to 2078 m with 7 samples, yet only 6 points enter the Pickett fit. Why?', '["The shallowest sample at 2075.0 m has a null deep resistivity and is dropped","The fit always discards the first sample as an edge guard","One sample fails the Vsh cutoff","The deepest sample lies below the free water level"]'::jsonb, 0, 'The 2075.0 m sample carries a null Rt, so the app silently drops it and reports nPoints = 6.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 8, 'The typewell Pickett fit returns which two values?', '["m = 1.8 and aRw = 0.031 ohm.m","m = 2.000 and aRw = 0.0500 ohm.m","m = 2.000 and Rw = 0.114 ohm.m","n = 2.000 and aRw = 0.0500 ohm.m"]'::jsonb, 1, 'The least-squares fit through the six water-leg points gives slope -2.000 and intercept 0.0500 ohm.m, matching the given parameter block.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 9, 'Two water-leg points read (phi 0.0990, Rt 5.1015) and (phi 0.0940, Rt 5.6587). The slope between them in log space is closest to:', '["-1.0","-4.0","-2.0","+2.0"]'::jsonb, 2, '(log 5.6587 - log 5.1015)/(log 0.0940 - log 0.0990) = 0.04503/(-0.02251) = -2.0007, so m = 2.0.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 10, 'Using aRw = Rt x phi^m with the water-leg point phi = 0.0990, Rt = 5.1015 ohm.m and m = 2, the product aRw is:', '["0.500 ohm.m","0.0500 ohm.m","0.0050 ohm.m","0.105 ohm.m"]'::jsonb, 1, '5.1015 x 0.0990^2 = 5.1015 x 0.009801 = 0.0500 ohm.m.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 11, 'Why does the app fit the Pickett line by least squares in log space rather than on the raw values?', '["Log-space fitting runs faster on large wells","Raw-value fitting would weight the high-resistivity end more heavily and the parameters would drift with the window''s porosity range","The resistivity tool records logarithms natively","Raw-value fitting cannot produce a negative slope"]'::jsonb, 1, 'Archie is a power law; fitting in log space weights every decade equally, which the power-law form requires.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 12, 'Iso-Sw lines on a Pickett plot are:', '["Curves that converge on the water line at high porosity","Lines of steeper slope than the water line","Horizontal lines at fixed resistivity","Lines parallel to the water line, offset upward by a factor 1/Sw^n in resistivity"]'::jsonb, 3, 'Fixing Sw adds the constant -n log Sw to the line equation, shifting it vertically without changing the slope -m.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 13, 'With n = 2, a sample at Sw = 0.5 sits how far above the water line in resistivity at the same porosity?', '["A factor of 4","A factor of 2","A factor of 8","A factor of 16"]'::jsonb, 0, 'The offset is 1/Sw^n = 1/0.5^2 = 4; each halving of Sw quadruples the resistivity offset.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 14, 'The mid SAND_A sample reads phi 0.1700 and Rt 9.2554 ohm.m, while the water line predicts 1.7301 ohm.m at that porosity, a ratio of 5.35. With n = 2, its water saturation is:', '["0.19","0.43","0.54","0.87"]'::jsonb, 1, 'Sw = 1/sqrt(5.35) = 0.4324, the same answer direct Archie arithmetic gives.'),
  ('petrophysics', 'intermediate', 'module', 'm04-the-pickett-plot', 15, 'Which parameter can a Pickett fit in a water leg never test?', '["The cementation exponent m","The product aRw","The saturation exponent n","The water-line slope"]'::jsonb, 2, 'n multiplies log Sw, which is zero everywhere in the leg, so a water leg is constitutionally incapable of constraining n.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 1, 'Why does the Archie equation systematically overestimate water saturation in shaly sand?', '["Shale lowers porosity, and Archie is undefined at low porosity","Clay minerals absorb the resistivity signal so the tool cannot read the formation","Clay adds a parallel conductive path, and Archie attributes that extra conductivity to more water","Shale raises the measured resistivity, which Archie converts into extra water"]'::jsonb, 2, 'Bound water on clay surfaces conducts in parallel with the pore brine. Archie has no clay term, so the only way it can explain the extra conductivity is with a higher water saturation.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 2, 'What do the Simandoux and Indonesia models return when Vsh equals zero?', '["A saturation about ten percent below Archie, reflecting the built-in shale correction","Exactly the Archie result, because both equations collapse onto Archie in clean rock","An undefined result, because both equations divide by Vsh","A saturation of one, because there is no clay to hold hydrocarbon"]'::jsonb, 1, 'Both equations are extensions of Archie whose shale terms vanish at Vsh = 0. On the typewell clean point at 2020 m all three models return 0.4324.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 3, 'At the typewell shale point at 2000 m, the three saturation models were evaluated on the same sample. Which ordering is correct?', '["Archie 0.8769, Simandoux 0.5730, Indonesia 0.4672","Indonesia 0.8769, Simandoux 0.5730, Archie 0.4672","Simandoux 0.8769, Archie 0.5730, Indonesia 0.4672","All three returned 0.4324 because the sample is a QC point"]'::jsonb, 0, 'Archie, blind to clay conductivity, reads highest. Simandoux removes part of the clay signal, and Indonesia, whose shale term is strongest at high Vsh, reads lowest.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 4, 'In the quadratic solution of the Simandoux equation, Sw = (-D + sqrt(D^2 + 4C/Rt)) / (2C), what is the physical meaning of D?', '["The clean-sand conductivity coefficient, phi^m divided by a times Rw","The deep resistivity corrected for invasion","The saturation exponent inherited from Archie","The clay-path conductivity coefficient, Vsh divided by Rsh"]'::jsonb, 3, 'D = Vsh/Rsh is the shale conductivity term. It enters the numerator with a negative sign: the stronger the clay path, the less conductivity remains to be explained by water.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 5, 'What saturation exponent does the classic Simandoux form carry?', '["Whatever n the interpreter supplies, like Archie","An inherent n of 2, fixed by the quadratic in Sw","An exponent that varies with shale volume","No saturation exponent at all"]'::jsonb, 1, 'Sw appears squared in the conductivity balance, so n = 2 is built into the equation. A basin whose core work demands a different n cannot be honoured by classic Simandoux.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 6, 'Where does the shale resistivity Rsh used by both shaly-sand models come from on the typewell?', '["It is computed from the gamma ray clay anchor","It is the Pickett plot intercept at porosity one","It is read from the deep resistivity in a thick shale, where the curve flattens at 2 ohm.m","It is a worldwide constant of 2 ohm.m for tertiary basins"]'::jsonb, 2, 'Rsh is a log reading, taken in a thick, representative shale where the deep resistivity is flat and unaffected by adjacent beds. On the typewell that reading is 2.0 ohm.m.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 7, 'In the Indonesia equation, what exponent is applied to Vsh in the shale term?', '["1 minus Vsh/2, an exponent that itself depends on the shale volume","Exactly 1, making the term linear in Vsh","Exactly 2, matching the cementation exponent","m/2, sharing the porosity exponent"]'::jsonb, 0, 'Poupon and Leveaux raised Vsh to the power (1 - Vsh/2), close to linear at low shaliness and approaching a square root as Vsh nears one, so a single equation tracks the whole range.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 8, 'Which model usually reads the lowest water saturation in very shaly rock, and why?', '["Archie, because high resistivity in shale implies hydrocarbon","Simandoux, because its quadratic amplifies the clay term","They all agree in shale, because the models are calibrated there","Indonesia, because its Vsh exponent makes the shale term grow fastest as shaliness climbs"]'::jsonb, 3, 'At high Vsh the Indonesia exponent (1 - Vsh/2) falls toward one half, strengthening the shale term relative to Simandoux''s linear Vsh/Rsh, so Indonesia removes the most conductivity from the water account.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 9, 'What SAND_A zone mean does the capstone expect for the Simandoux model?', '["0.4478, within 0.01","0.4335, within 0.01","0.4280, within 0.01","0.5730, within 0.01"]'::jsonb, 1, 'The graded Simandoux mean over 2010 to 2030 m is 0.4335. The 0.4280 value is the Indonesia mean, 0.4478 is the ungraded Archie baseline, and 0.5730 is the single shale-point Simandoux value.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 10, 'Why do all three saturation models read exactly 1.0 in the typewell water leg?', '["The leg is clean, so both shaly-sand models collapse to Archie, and Archie reads fully wet in the interval that defined a times Rw","The app clamps every model to 1.0 below the oil-water contact","The neutron-density porosity is zero there, forcing saturation to its ceiling","The shale term saturates at Vsh = 1 in the leg"]'::jsonb, 0, 'Vsh is zero in the leg, so Simandoux and Indonesia become Archie, and the leg is the interval whose samples fixed a times Rw, so Archie reads Sw = 1 there by construction. The leg is a three-model QC point.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 11, 'According to the original calibrations, which conditions favour choosing the Indonesia model over Simandoux?', '["Saline formation water and dispersed clay","Carbonate reservoirs with vuggy porosity","Fresher formation water and laminated shale sequences","Any reservoir where core data are available"]'::jsonb, 2, 'Poupon and Leveaux built the equation for the fresh-water, laminated shaly sands of Indonesia. Simandoux came from dispersed clay and relatively saline waters. Local calibration overrides provenance when available.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 12, 'What happens to a shaly-sand saturation if the interpreter overstates Vsh or understates Rsh?', '["The result rises toward the Archie baseline","Nothing, because the two errors always cancel","The model becomes undefined","The clay term removes too much conductivity and Sw comes out optimistically low"]'::jsonb, 3, 'The correction scales with Vsh/Rsh. Inflating that ratio assigns too much of the measured conductivity to clay, leaving too little to be explained by water, so the model understates Sw and overstates pay.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 13, 'At the clean point at 2020 m, with porosity 0.1700 and deep resistivity 9.2554 ohm.m, what do the three models return?', '["Three different values spanning about 40 saturation points","All three return 0.4324","Archie returns 0.4324 and the shaly-sand models return lower values","All three return 1.0000 because the sample is wet"]'::jsonb, 1, 'Vsh is zero at this sample, so the shale terms vanish and every model evaluates the same Archie expression, returning 0.4324 to four decimals.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 14, 'The spread between the three model means in SAND_A is under 0.02 saturation units. What is the correct professional reading of that spread?', '["The zone is fundamentally a clean sand, and the model choice is not the dominant uncertainty there","The models are wrong, because they should diverge in pay","The tolerance of the capstone is too tight to grade the zone","The zone is a shale, because only shale makes models converge"]'::jsonb, 0, 'Models converge where Vsh is small and diverge where it is large. A narrow spread in the booked zone confirms the rock is clean and the correction modest; wide spread flags rock where the Vsh and Rsh inputs dominate.'),
  ('petrophysics', 'intermediate', 'module', 'm05-shaly-sand-saturation', 15, 'Why does this course feed the shaly-sand models a linear Vsh rather than a Larionov transform?', '["Linear Vsh is the only transform the equations accept mathematically","Larionov requires core data that the typewell lacks","A conservative upper bound on clay keeps the shale correction honest; a flattering Vsh would shrink the correction back toward Archie","Linear Vsh is faster to compute at 0.5 m sampling"]'::jsonb, 2, 'The size of the correction scales with Vsh. Feeding the models a transform that minimises clay volume quietly gives back the accuracy the shaly-sand equations were adopted to gain, so a deliberate upper bound is used instead.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 1, 'In the SAND_A sensitivity experiment, only the saturation model was changed between runs. What happened to booked net pay?', '["Archie booked 19.0 m while Simandoux and Indonesia each booked 20.0 m","All three models booked identical net pay because the porosity was held constant","Indonesia booked the least net pay because it computes the highest saturations","Net pay changed by less than a tenth of a metre across the models"]'::jsonb, 0, 'With phiND, linear Vsh and standard cutoffs held constant, Archie books 19.0 m net while both shaly-sand models book 20.0 m: a full metre flips on the model choice.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 2, 'Why can a saturation difference of only about 0.01 between models move a whole metre of net pay?', '["Because the porosity curve is recomputed whenever the saturation model changes","Because samples near the Sw cutoff flip sides of it, and the pay flag is a discrete step function","Because the gross interval shrinks when saturation rises","Because zone means are always rounded to two decimal places before booking"]'::jsonb, 1, 'The cutoff is a step applied to a continuous curve; wherever computed Sw grazes 0.6, tiny model differences flip whole samples in or out of the net count.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 3, 'In the sensitivity table, the Archie run reports a lower mean porosity (0.1752) than the shaly-sand runs (0.1762) even though the porosity curve was identical. Why?', '["Archie applies its own porosity correction before averaging","The density log was excluded from the Archie run","Zone means are computed over net samples only, and Archie excluded samples that carried slightly better porosity","Rounding in the NTG calculation propagates into the porosity mean"]'::jsonb, 2, 'Booked averages are conditional on the booking: changing which samples pass the cutoffs changes the membership of the averaged set, not the underlying curve.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 4, 'Which porosity method does the reconciliation framework book as primary on the typewell, and what is its SAND_A mean?', '["Density only, 0.2022","Wyllie sonic, 0.2069","Raymer-Hunt-Gardner, 0.2344","Neutron-density average, 0.1762"]'::jsonb, 3, 'phiND is primary because the neutron and density err in opposite directions in shale and gas; its SAND_A mean is 0.1762.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 5, 'What role does the sonic porosity keep in the reconciled evaluation even when it is never booked?', '["It is discarded once phiND is chosen","It is retained as the bad-hole backup because the sonic tolerates rugosity that wrecks the density pad","It replaces the neutron in gas intervals automatically","It is averaged into phiND to stabilise the estimate"]'::jsonb, 1, 'The sonic reads along the borehole wall and survives hole conditions that ruin pad contact, so it stays in the report as the stated backup.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 6, 'The SAND_A saturation spread across Archie, Simandoux and Indonesia is only about 0.02. What is the professional explanation?', '["The sand is clean, so with near-zero Vsh both shaly-sand equations collapse toward Archie","The three equations are algebraically identical whenever porosity exceeds 0.15","The resistivity log has low resolution, which compresses all model outputs","The cutoffs truncate the saturation distribution equally in all runs"]'::jsonb, 0, 'Both Simandoux and Indonesia degenerate to Archie as Vsh goes to zero; a small spread in a clean sand is the models agreeing where they should.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 7, 'According to the reconciliation lesson, what does a strong disagreement between methods primarily provide?', '["Proof that the logging data must be recalibrated before interpretation","Grounds for averaging the disagreeing methods to split the difference","A diagnostic that localises a physical problem such as shale, bad hole or gas","Justification for widening the cutoff values"]'::jsonb, 2, 'Where the methods split tells you what is wrong: porosity divergence in shale points at clay effects, density spikes point at bad hole, neutron-density crossover points at gas.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 8, 'Why does the course forbid blindly averaging Archie with Simandoux into a single booked saturation?', '["Because Simandoux always overestimates saturation in clean sand","Because averaging is only permitted for porosity methods, never for any other quantity","Because the two models use different porosity inputs","Because the average is not the solution of any saturation equation and has unknown error behaviour"]'::jsonb, 3, 'A booked number must be the output of a named method chosen for a stated reason; an ad hoc model average has no physics behind it.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 9, 'In the professional report, every parameter is labelled with one of three provenance categories. Which set is correct?', '["Given, fitted, assumed","Measured, interpolated, guessed","Primary, secondary, tertiary","Raw, corrected, normalised"]'::jsonb, 0, 'Each parameter is recorded as given with the dataset, fitted from this well''s own data, or assumed from experience, with the source stated.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 10, 'How should the Pickett-derived parameters appear in the report''s parameter table?', '["As given values, since the dataset was built with Rw 0.05","As fitted values: aRw 0.0500 ohm.m and m 2.000 from the 6-point fit over 2075 to 2078 m","As assumed values carried from an analogue field","They are omitted because the grader recomputes them anyway"]'::jsonb, 1, 'They were derived from this well''s own water leg, so they are fitted, and quoting the window and point count lets a reader reproduce the fit exactly.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 11, 'What is the reproducibility test a professional report must pass before it is issued?', '["The app must export it without warnings","The zone tables must quote at least four significant figures","Another professional, given only the report and the dataset, could rerun the workflow and land on the same numbers","Every method used must have a journal reference attached"]'::jsonb, 2, 'If any step forces the reader to guess a curve, parameter, method or window, the report fails regardless of polish.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 12, 'Which six quantities does the Professional capstone grade?', '["Net, gross and NTG for SAND_A and SAND_B","IGR, Vsh and phiD at three graded depths","Rw, Rsh, a, m, n and the Sw cutoff","Two SAND_A porosity means (neutron-density and Wyllie sonic), the Pickett aRw and m, and two SAND_A shaly-sand Sw means (Simandoux and Indonesia)"]'::jsonb, 3, 'The capstone is the course in miniature: two numbers each from the porosity, Pickett and shaly-sand modules.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 13, 'On the deep path, what must be completed before the Professional capstone unlocks?', '["All lessons in order, every module quiz passed at 75 percent, and the final exam passed at 70 percent","Only the final exam, since the quizzes are optional practice","A passing Expert tier enrolment","Submission of a draft report for admin review"]'::jsonb, 0, 'The capstone is the last step: sequential lessons, module quizzes at 75 percent, then the final exam at 70 percent, all enforced server-side.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 14, 'Before submitting the capstone, which sanity check on the two porosity means should you perform?', '["They should be identical within rounding","The neutron-density mean should sit below the Wyllie sonic mean, in the order the reconciliation predicts","The Wyllie mean should equal the density-only mean exactly","Both should exceed the porosity cutoff of 0.08 by at least a factor of three"]'::jsonb, 1, 'On the typewell phiND (0.1762) must land below the Wyllie mean (0.2069); if the order is wrong, something upstream is broken.'),
  ('petrophysics', 'intermediate', 'module', 'm06-method-choice-and-reporting', 15, 'What capability does the Expert tier add beyond the Professional workflow?', '["Automated cutoff optimisation across zones","Multi-well batch interpretation of the full field","Triangulating Rw itself from a temperature-corrected lab sample, an SP quicklook and the Pickett fit","Replacing the Archie family with resistivity-independent saturation methods"]'::jsonb, 2, 'The Expert course attacks Rw from three independent directions, including the Arps temperature correction and the SP log, and shows what a wrong Rw does to booked pay.'),
  ('petrophysics', 'intermediate', 'final', null, 1, 'The intermediate course replaces Larionov tertiary with the linear Vsh transform. What is the main reason for that switch?', '["Linear Vsh is more accurate than Larionov in every basin","Shaly-sand saturation work wants a deliberately conservative upper bound on clay volume as its input","The gamma ray tool cannot support nonlinear transforms at this tier","Larionov tertiary only applies to carbonate sections"]'::jsonb, 1, 'The shaly-sand equations were calibrated with conservative clay volumes, and a deliberate upper bound keeps the saturation correction honest. Linear is a choice about conservatism, and accuracy claims per basin or tool limitations play no part.'),
  ('petrophysics', 'intermediate', 'final', null, 2, 'Using the typewell anchors (clean 20 API, clay 120 API), what is the linear Vsh for a sample reading GR = 70 API?', '["0.50","0.2162","0.70","0.30"]'::jsonb, 0, 'IGR = (70 - 20)/(120 - 20) = 0.50 and the linear transform takes the index as the volume. 0.2162 is the Larionov tertiary value at the same index, which the intermediate workflow does not use.'),
  ('petrophysics', 'intermediate', 'final', null, 3, 'A sample reads GR = 140 API against anchors of 20 (clean) and 120 (clay). What linear Vsh does the workflow assign?', '["1.20, because the index may exceed one","0.86, by rescaling the anchors","The sample is discarded from the interpretation","1.00, because the index is clamped to the range 0 to 1"]'::jsonb, 3, 'The raw index is (140 - 20)/100 = 1.20, but Vsh is a volume fraction, so the workflow clamps it to 1.00. GR wandering outside the anchors is exactly why clamping exists.'),
  ('petrophysics', 'intermediate', 'final', null, 4, 'Which two curves join the interpretation at the Professional tier, beyond the GR, RHOB and RT used at Associate level?', '["SP and caliper","PEF and spectral gamma ray","NPHI and DT","Rxo and density correction"]'::jsonb, 2, 'The intermediate workflow brings in the neutron log (NPHI, hydrogen index in porosity units) and the sonic log (DT, compressional transit time) to build multi-method porosity.'),
  ('petrophysics', 'intermediate', 'final', null, 5, 'Why does the intermediate workflow fit the Pickett line in the water leg before running the saturation models?', '["The fit removes the shale effect from the resistivity curve","The fit validates a times Rw and m from the data itself before those parameters are used in every saturation equation","The Pickett plot computes porosity, which the models need first","The fit determines the saturation exponent n"]'::jsonb, 1, 'With Sw = 1 in the leg, Archie collapses to a straight line in log space whose slope and intercept confirm m and the product a times Rw. Those parameters feed every saturation model, so they are checked first. The exponent n never enters a water-leg fit.'),
  ('petrophysics', 'intermediate', 'final', null, 6, 'The shale resistivity rsh = 2.0 ohm.m used by the typewell saturation models comes from where?', '["A regional database of shale resistivities","The Pickett plot intercept","The resistivity read directly in the thick shale, where RT flattens at 2 ohm.m","The product of Rw and the cementation exponent"]'::jsonb, 2, 'Rsh is read from the log itself in a thick, representative shale interval. On the typewell RT flattens at 2 ohm.m in the shale, and that reading becomes the model input.'),
  ('petrophysics', 'intermediate', 'final', null, 7, 'At IGR = 0.5 the linear transform gives Vsh = 0.50 while Larionov tertiary gives 0.2162. Which statement about Vsh transforms is correct?', '["They disagree at IGR = 0 and IGR = 1 but agree in the middle","Larionov tertiary always reads higher than linear","They agree at the end points and differ in between, where Larionov sags below the one-to-one line","The two transforms are identical for young clastic sections"]'::jsonb, 2, 'All the standard transforms return 0 at IGR = 0 and 1 at IGR = 1 (Larionov tertiary gives 0.996, which is 1 within the precision of its empirical constant). Between the ends Larionov sags below linear, which is why linear is the conservative upper bound.'),
  ('petrophysics', 'intermediate', 'final', null, 8, 'Using the typewell values dt_ma = 182 us/m and dt_fl = 656 us/m, what Wyllie porosity corresponds to DT = 300.5 us/m?', '["0.185","0.458","0.302","0.250"]'::jsonb, 3, 'phi = (300.5 - 182)/(656 - 182) = 118.5/474 = 0.250. The distractor 0.458 comes from dividing by the fluid value instead of the matrix-to-fluid span.'),
  ('petrophysics', 'intermediate', 'final', null, 9, 'At the clean mid SAND_A sample (DT = 281.54 us/m) Wyllie gives 0.2100 and Raymer-Hunt-Gardner gives 0.2369. Why does RHG read higher here?', '["RHG uses the fluid transit time twice","RHG was fitted to field data without a separate compaction correction, so it sits above an uncorrected Wyllie across the mid porosity range","RHG includes the neutron reading in its formula","Wyllie is wrong whenever the rock is water filled"]'::jsonb, 1, 'RHG is an empirical fit built to match observed porosities across the full range without a Cp term, and in this range it reads above the plain Wyllie time average. Neither formula uses the neutron log.'),
  ('petrophysics', 'intermediate', 'final', null, 10, 'The typewell sonic values are quoted as 182 us/m matrix and 656 us/m fluid. Their imperial equivalents are approximately:', '["55.5 us/ft and 200 us/ft, the classic sandstone matrix and water values","182 us/ft and 656 us/ft, since the unit does not change the number","18.2 us/ft and 65.6 us/ft","89 us/ft and 320 us/ft"]'::jsonb, 0, 'One foot is 0.3048 m, so 182 us/m x 0.3048 = 55.5 us/ft and 656 us/m x 0.3048 = 200 us/ft, the familiar textbook pair for quartz sandstone and water.'),
  ('petrophysics', 'intermediate', 'final', null, 11, 'As a consistency check of the Wyllie equation end points with dt_ma = 182 and dt_fl = 656 us/m, what porosity does DT = 656 us/m return?', '["0, because the reading equals the matrix value","0.5, the midpoint of the scale","1, because the reading equals the fluid value","The equation is undefined at that reading"]'::jsonb, 2, 'phi = (656 - 182)/(656 - 182) = 1. A reading at the fluid transit time means the acoustic path is all fluid, and at DT = 182 the same check returns 0.'),
  ('petrophysics', 'intermediate', 'final', null, 12, 'A washed-out interval stretches the measured transit time beyond the formation value. What does that do to sonic porosity?', '["Nothing, the sonic is a pad tool immune to hole size","It lowers apparent porosity because the path shortens","It converts the reading to matrix transit time","It raises apparent porosity, because a longer DT maps to more fluid in the Wyllie equation"]'::jsonb, 3, 'Anything that lengthens the transit time (washouts, cycle skipping onto a later arrival) pushes the Wyllie result upward. That is why sonic porosity needs hole-condition QC before it is booked.'),
  ('petrophysics', 'intermediate', 'final', null, 13, 'In which situation would a professional prefer Raymer-Hunt-Gardner over the plain Wyllie time average?', '["Uncompacted or slow formations, where Wyllie without a compaction correction underestimates porosity","Tight cemented quartzites at very low porosity","Whenever the density log is available","Water legs, where saturation is known"]'::jsonb, 0, 'RHG was designed to fit observations across the porosity range without a separate Cp factor, so it is the natural pick where Wyllie would need a compaction correction. Density availability and water legs are unrelated to the sonic model choice.'),
  ('petrophysics', 'intermediate', 'final', null, 14, 'SAND_A zone means on the typewell are 0.2069 (Wyllie), 0.2344 (RHG) and 0.2022 (density). What is the professional conclusion from that spread?', '["The density log has failed in SAND_A","The spread is a matter of model choice, so the report must state which porosity method was booked and why","RHG is correct because it is the largest","The average of the three should always be booked"]'::jsonb, 1, 'All three are legitimate computations from good data; the differences come from the models. The obligation is to state and defend the booked method, never to assume the largest or a blind average is right.'),
  ('petrophysics', 'intermediate', 'final', null, 15, 'A clean sand sample reads RHOB = 2.32 g/cc and NPHI = 0.14 with matrix 2.65 and fluid 1.0. What is the neutron-density porosity by the course''s average method?', '["0.14","0.20","0.17","0.34"]'::jsonb, 2, 'phiD = (2.65 - 2.32)/1.65 = 0.20, and phiND = (0.20 + 0.14)/2 = 0.17. The 0.34 distractor is the sum instead of the average.'),
  ('petrophysics', 'intermediate', 'final', null, 16, 'Why does the neutron log read high in shale?', '["Clay-bound water contributes hydrogen that the tool cannot separate from pore-filling water","Shale is more radioactive, and the neutron tool responds to radioactivity","Shale has higher electron density than sand","The neutron source loses calibration opposite clay minerals"]'::jsonb, 0, 'The tool responds to hydrogen index. Water bound to clay surfaces carries hydrogen without contributing effective porosity, so NPHI is inflated in shale. Radioactivity drives the gamma ray, not the neutron.'),
  ('petrophysics', 'intermediate', 'final', null, 17, 'In the typewell shale at 2000 m, phiD = 0.0606 and NPHI = 0.30, so phiND = 0.1803. How should that 0.1803 be understood?', '["As effective porosity available to producible fluids","As a tool failure to be edited out","As gas-affected porosity","As an apparent porosity dominated by clay-bound water, not effective pore space"]'::jsonb, 3, 'The neutron''s clay-bound hydrogen drags the combination upward in shale. The number is real arithmetic on real readings, but it is apparent porosity; a shale correction (for example 0.1803 - Vsh x 0.10 = 0.0803 at Vsh = 1) moves it toward effective.'),
  ('petrophysics', 'intermediate', 'final', null, 18, 'On a compatible-scale neutron-density overlay, what is the classic gas signature?', '["Both curves read high together","Crossover: density porosity reads high while neutron porosity reads low","Both curves read low together","The curves track exactly with no separation"]'::jsonb, 1, 'Gas lowers bulk density (raising phiD) and lowers hydrogen index (lowering NPHI), pulling the curves in opposite directions. The typewell shows no crossover because it holds only oil and water, and that absence is itself diagnostic.'),
  ('petrophysics', 'intermediate', 'final', null, 19, 'The app''s neutron-density crossplot draws three matrix lines. Which lithologies are they?', '["Sandstone, shale and coal","Quartz, feldspar and mica","Sandstone, limestone and dolomite","Anhydrite, salt and limestone"]'::jsonb, 2, 'The standard chartbook trio. A point on a matrix line carries that lithology reading and its position along the line gives porosity; shale pulls points off the lines toward high NPHI and low density porosity.'),
  ('petrophysics', 'intermediate', 'final', null, 20, 'Apply the linear shale correction phi_e = phi - Vsh x phi_shale_apparent to the shale point: phiND = 0.1803, Vsh = 1.0, apparent shale porosity 0.10. The corrected value is:', '["0.0803","0.1803","0.1000","0.0100"]'::jsonb, 0, '0.1803 - 1.0 x 0.10 = 0.0803. The correction removes the clay-bound contribution in proportion to shale volume.'),
  ('petrophysics', 'intermediate', 'final', null, 21, 'Why does the intermediate course book neutron-density porosity rather than density porosity alone?', '["Because the neutron log is more accurate than the density log","Because phiND is always lower and lower is safer","Because the capstone rejects density porosity","Because combining two tools with opposing error directions tempers single-tool artefacts before the value feeds the Pickett fit and the saturation models"]'::jsonb, 3, 'Density and neutron errors run opposite ways in shale and gas, so their average is more robust than either alone. phiND is not systematically lower everywhere, and no tool is simply more accurate than the other.'),
  ('petrophysics', 'intermediate', 'final', null, 22, 'Rearranging Archie at Sw = 1 into log space gives log RT = log(a Rw) - m log phi. On a Pickett plot the water line therefore has:', '["Slope +m and intercept Rw at phi = 0","Slope -n and intercept a at phi = 1","Slope +1/m and intercept Rt at phi = 0.1","Slope -m, with the extrapolated RT at phi = 1 equal to a times Rw"]'::jsonb, 3, 'The cementation exponent appears as the negative slope in log-log space, and setting phi = 1 makes the porosity term vanish so the line reads a times Rw directly.'),
  ('petrophysics', 'intermediate', 'final', null, 23, 'A water-leg sample reads phi = 0.0990 and RT = 5.1015 ohm.m with m = 2. What a times Rw does that single point imply?', '["0.505","0.0500","0.101","0.0099"]'::jsonb, 1, 'At Sw = 1, a Rw = RT x phi^m = 5.1015 x 0.0990^2 = 5.1015 x 0.009801 = 0.0500 ohm.m, matching the typewell''s given rw = 0.05 with a = 1.'),
  ('petrophysics', 'intermediate', 'final', null, 24, 'The typewell water leg spans 2075 to 2078 m with samples every 0.5 m, yet the Pickett fit uses 6 points. Why?', '["The 2075.0 m sample has a null resistivity reading, so it drops from the fit","The fit always discards the deepest point","Only even-numbered depths are used","The app limits every fit to 6 points"]'::jsonb, 0, 'Seven depths fall in the window but the shallowest carries no RT value, leaving six valid points. A fit only uses samples where both phi and RT exist.'),
  ('petrophysics', 'intermediate', 'final', null, 25, 'With n = 2, by what resistivity factor does the Sw = 0.5 iso-line sit above the water line on a Pickett plot?', '["A factor of 8","A factor of 0.25","A factor of 2","A factor of 4"]'::jsonb, 3, 'Iso-Sw lines are offset by 1/Sw^n in RT. For Sw = 0.5 and n = 2 that is 1/0.25 = 4 times the water-line resistivity at every porosity.'),
  ('petrophysics', 'intermediate', 'final', null, 26, 'Which parameter is NOT validated by a water-leg Pickett fit?', '["The cementation exponent m","The saturation exponent n","The product a times Rw","The consistency of the given Rw with the leg, assuming a = 1"]'::jsonb, 1, 'With Sw = 1 everywhere in the leg, the Sw^n term is identically 1 and n never enters the fit. The slope checks m and the intercept checks the a Rw product; a and Rw individually stay entangled.'),
  ('petrophysics', 'intermediate', 'final', null, 27, 'The water line with a Rw = 0.05 and m = 2 predicts RT = 0.05/0.17^2 = 1.7301 ohm.m at phi = 0.17. The mid SAND_A sample reads RT = 9.2554 there. With n = 2, the implied Sw is:', '["About 0.43, from one over the square root of the ratio 5.35","About 0.19, the inverse of the ratio","About 1.0, since the point lies near the line","About 0.65, from one over the ratio to the power 1/4"]'::jsonb, 0, 'The sample sits a factor 9.2554/1.7301 = 5.35 above the water line, and Sw = (1/5.35)^(1/n) = 1/sqrt(5.35) = 0.4324. This reproduces the Archie value computed directly from the equation.'),
  ('petrophysics', 'intermediate', 'final', null, 28, 'Which situation most directly invalidates a Pickett fit taken through an apparent water leg?', '["The leg lies below the free water level","The leg has more than ten samples","The leg is actually a transition zone where Sw is below 1","The porosity in the leg varies from sample to sample"]'::jsonb, 2, 'The method assumes Sw = 1 exactly. In a transition zone the points sit above the true water line, biasing both slope and intercept. Porosity variation is what spreads the points along the line and helps the fit.'),
  ('petrophysics', 'intermediate', 'final', null, 29, 'Why does Archie read water saturation too HIGH in shaly sand?', '["Clay minerals raise the resistivity of the formation","The gamma ray correction is not applied to RT","Shale lowers porosity below the Archie range","Clay surfaces add a parallel conductive path, and Archie attributes all conductivity to brine in clean pores"]'::jsonb, 3, 'The rock conducts more than Archie expects because clay-bound water conducts alongside the pore brine. Extra conductivity is misread as extra water, inflating Sw. On the typewell shale point Archie gives 0.8769 against Simandoux 0.5730.'),
  ('petrophysics', 'intermediate', 'final', null, 30, 'At the clean mid SAND_A sample (linear Vsh = 0), Archie, Simandoux and Indonesia all return exactly 0.4324. What does that demonstrate?', '["Both shaly-sand models degenerate exactly to Archie when Vsh is zero, so the correction only acts where clay exists","The three models are algebraically identical everywhere","The sample must lie in the water leg","The saturation exponent has no effect in clean rock"]'::jsonb, 0, 'Setting Vsh = 0 removes the shale conduction term from both models and each collapses to Archie. Away from clean rock the models diverge, as the shale point shows (0.8769 vs 0.5730 vs 0.4672).'),
  ('petrophysics', 'intermediate', 'final', null, 31, 'The Simandoux model as implemented is 1/Rt = phi^m Sw^2/(a Rw) + Vsh Sw/Rsh. How is Sw obtained from it?', '["By iterating from an Archie starting guess","As the positive root of a quadratic in Sw, with n = 2 inherent in the squared term","By taking logarithms of both sides","By setting the shale term to zero and inverting"]'::jsonb, 1, 'The equation is quadratic in Sw, solved in closed form for the positive root. The exponent 2 on Sw is built into the classic form, which is why the engine''s Simandoux takes no separate n parameter.'),
  ('petrophysics', 'intermediate', 'final', null, 32, 'In the Indonesia (Poupon-Leveaux) model the shale term carries Vsh raised to the power (1 - Vsh/2). At Vsh = 1 that exponent evaluates to:', '["1.0","0.25","0.5","0.0"]'::jsonb, 2, '1 - 1/2 = 0.5, so pure shale enters as the square root of Vsh divided by the square root of Rsh. The variable exponent is the model''s empirical device for spanning laminated and dispersed clay behaviour.'),
  ('petrophysics', 'intermediate', 'final', null, 33, 'On the typewell shale point the three models give Archie 0.8769, Simandoux 0.5730 and Indonesia 0.4672. Which general ordering does this illustrate at high Vsh?', '["Simandoux always reads above Archie","The ordering is random from sample to sample","Archie reads lowest because it ignores clay","Shaly-sand models read at or below Archie, with Indonesia usually lowest because its shale term grows fastest"]'::jsonb, 3, 'Correcting for clay conductivity can only reduce the water Archie wrongly infers, and the Indonesia shale term strengthens quickest as Vsh rises, putting it lowest of the three in shaly rock.'),
  ('petrophysics', 'intermediate', 'final', null, 34, 'SAND_A zone means are Archie 0.4478, Simandoux 0.4335 and Indonesia 0.4280. Why is the spread between the models so small in this zone?', '["The sand is clean, so the linear Vsh input is near zero and the shale corrections barely act","The zone means are computed only in the water leg","The models share the same shale term","Rsh was chosen to force agreement"]'::jsonb, 0, 'The correction scales with Vsh. SAND_A is a clean sand, so all three models stay near the Archie baseline; explaining WHY the spread is small is part of a professional reconciliation.'),
  ('petrophysics', 'intermediate', 'final', null, 35, 'Which pairing of shaly-sand model to setting matches the course guidance?', '["Indonesia for saline dispersed shale; Simandoux for fresh laminated shale","Simandoux for the general dispersed-shale case with saline water; Indonesia for fresher formation water and laminated shale","Either model, chosen by whichever gives lower Sw","Archie for shale, Simandoux for clean sand"]'::jsonb, 1, 'Simandoux is the general dispersed-clay workhorse in saline water; Poupon and Leveaux built Indonesia for fresh-water, laminated shaly sands. Choosing by lowest answer is advocacy, not petrophysics.'),
  ('petrophysics', 'intermediate', 'final', null, 36, 'Booked with identical porosity, Vsh and cutoffs, SAND_A net pay is 19.0 m under Archie but 20.0 m under Simandoux and Indonesia. What causes a full metre to appear?', '["The models compute different porosities","The gross interval changes with the model","Rounding in the zone means","Samples sitting just above the Sw = 0.6 cutoff under Archie fall just below it under the shaly-sand models, flipping their pay flags"]'::jsonb, 3, 'Cutoffs turn small continuous differences into discrete flag flips. The shaly-sand models read slightly lower Sw, and near-cutoff samples cross the 0.6 line; porosity and gross thickness are identical across the three runs.'),
  ('petrophysics', 'intermediate', 'final', null, 37, 'A sample has phi = 0.09, Vsh = 0.40, Archie Sw = 0.62 and Simandoux Sw = 0.58. With cutoffs phi >= 0.08, Vsh <= 0.5 and Sw <= 0.6, how is it flagged?', '["Pay under both models","Pay under Simandoux only","Pay under Archie only","Not pay under either model"]'::jsonb, 1, 'Porosity and Vsh pass in both runs. Archie''s 0.62 fails the Sw cutoff while Simandoux''s 0.58 passes it, so the flag flips with the model, which is precisely the sensitivity the net-pay lesson quantifies.'),
  ('petrophysics', 'intermediate', 'final', null, 38, 'What does the course mean by reconciling porosity and saturation methods?', '["Explaining the differences between methods from physics, then booking a stated choice with its justification","Averaging all methods to a single compromise value","Booking the method that maximises net pay","Rerunning methods until they agree"]'::jsonb, 0, 'Disagreement localises problems (shale, bad hole, gas) and small spreads have physical reasons too. Blind averaging and answer-shopping both destroy the audit trail a professional evaluation needs.'),
  ('petrophysics', 'intermediate', 'final', null, 39, 'In the professional report, every parameter should be recorded together with:', '["The initials of the logging engineer","Its provenance: whether it was given, fitted from the data, or assumed","Its value in both metric and imperial units","The date the tool was calibrated"]'::jsonb, 1, 'Provenance is what makes the evaluation defensible: the Pickett-confirmed a Rw 0.0500 and m 2.000 are fitted, the cutoffs are given, an Rsh from a neighbouring well would be assumed. A reader must know which is which.'),
  ('petrophysics', 'intermediate', 'final', null, 40, 'The reproducibility standard the course sets for a professional evaluation is that:', '["The report is signed by two engineers","The workflow runs in under one minute","The raw curves are archived with the report","Another professional, given the report alone, reruns the workflow and lands on the same numbers"]'::jsonb, 3, 'Curves and signatures help, but the operational test is that the documented inputs, parameters and method choices are complete enough to regenerate the results, including the six capstone numbers.'),
  ('petrophysics', 'intermediate', 'final', null, 41, 'Which six quantities does the Professional capstone grade on the typewell?', '["SAND_A mean neutron-density porosity, SAND_A mean Wyllie sonic porosity, Pickett a times Rw, Pickett m, SAND_A mean Simandoux Sw, SAND_A mean Indonesia Sw","Net, gross and NTG for SAND_A and SAND_B","Vsh, phiD and Sw at three named depths","Rw, Rsh, a, m, n and the Sw cutoff"]'::jsonb, 0, 'Two porosity means, the two Pickett fit results and the two shaly-sand saturation means, all on SAND_A with the fit taken in the 2075 to 2078 m water leg.'),
  ('petrophysics', 'intermediate', 'final', null, 42, 'On the deep course path, what must a learner complete before the Professional capstone submission unlocks?', '["A resit of the Associate capstone","An interview with a lecturer","All lessons, every module quiz and a passing final exam, enforced in that order by the server","Only the module on method choice and reporting"]'::jsonb, 2, 'The deep path sequences the work: lessons unlock in order, each module quiz gates progress, and the final exam must be passed before the capstone practical opens. The capstone remains the graded exercise that certifies the tier.');
